// Help-center state and reports. Pure functions over one plain object.
import { slugify, plain, headings } from "./markdown.mjs";
import { buildIndex, search, tokens } from "./search.mjs";

const clean = (s, n) => String(s ?? "").replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "").trim().slice(0, n);
const oneLine = (s, n) => clean(s, n).replace(/\s+/g, " ");

export function newState() {
  return { settings: { name: "Help Center", tagline: "Search for answers", contact: "" }, articles: {}, queries: {}, feedback: [], seq: 1, rev: 0 };
}

export function updateSettings(state, f) {
  const s = state.settings;
  if (f.name !== undefined) s.name = oneLine(f.name, 80) || "Help Center";
  if (f.tagline !== undefined) s.tagline = oneLine(f.tagline, 140);
  if (f.contact !== undefined) {
    const c = oneLine(f.contact, 300);
    if (c && !/^(https?:\/\/[^\s"'<>]+|mailto:[^\s"'<>]+|[^\s@"'<>]+@[^\s@"'<>]+\.[^\s@"'<>]+)$/i.test(c)) throw new Error("contact must be an https:// link or an email address");
    s.contact = c;
  }
  state.rev++; return s;
}
export const contactHref = (c) => (!c ? "" : /^https?:|^mailto:/i.test(c) ? c : `mailto:${c}`);

export function saveArticle(state, f, now) {
  const title = oneLine(f.title, 140); if (!title) throw new Error("give the article a title");
  const body = clean(f.body, 60_000); if (!body) throw new Error("the article is empty");
  const existing = f.id ? state.articles[f.id] : null;
  if (f.id && !existing) throw new Error("no such article");
  let slug = slugify(f.slug || title) || "article";
  const taken = (s) => Object.values(state.articles).some((a) => a.slug === s && a.id !== existing?.id);
  if (f.slug && taken(slug)) throw new Error(`the address "${slug}" is already used by another article`);
  for (let n = 2; taken(slug); n++) slug = `${slugify(f.slug || title).slice(0, 55)}-${n}`;
  const status = f.status === "published" ? "published" : "draft";
  const tags = [...new Set(String(f.tags || "").split(",").map((t) => oneLine(t, 30).toLowerCase()).filter(Boolean))].slice(0, 10);
  const a = existing || { id: `a${state.seq++}`, created: now, views: 0, yes: 0, no: 0 };
  Object.assign(a, { slug, title, body, tags, status, collection: oneLine(f.collection, 60) || "General", updated: now });
  state.articles[a.id] = a; state.rev++; return a;
}
export const removeArticle = (state, id) => (state.articles[id] ? (delete state.articles[id], state.rev++, true) : false);
export const published = (state) => Object.values(state.articles).filter((a) => a.status === "published");
export const bySlug = (state, slug) => Object.values(state.articles).find((a) => a.slug === slug);

// Bulk import: articles separated by a line of =====, each optionally starting with --- front matter --- (title, collection, tags, status, slug).
export function importMarkdown(state, text, now) {
  let n = 0; const errors = [];
  for (const [i, doc] of String(text).replace(/\r\n?/g, "\n").split(/^={5,}\s*$/m).entries()) {
    if (!doc.trim()) continue;
    const m = /^\s*---\n([\s\S]*?)\n---\n?([\s\S]*)$/.exec(doc);
    const meta = {}; let body = doc.trim();
    if (m) { for (const line of m[1].split("\n")) { const k = /^(\w+):\s*(.*)$/.exec(line); if (k) meta[k[1].toLowerCase()] = k[2].trim(); } body = m[2].trim(); }
    if (!meta.title) { const h = /^#\s+(.+)$/m.exec(body); if (h) { meta.title = h[1].trim(); body = body.replace(/^#\s+.+\n?/m, "").trim(); } }
    try { saveArticle(state, { ...meta, body, status: meta.status || "draft", slug: undefined }, now); n++; } catch (e) { errors.push(`article ${i + 1}: ${e.message}`); }
  }
  return { imported: n, errors };
}

let cache = new WeakMap();
export function indexOf(state, { drafts = false } = {}) {
  let c = cache.get(state); if (!c || c.rev !== state.rev) { c = { rev: state.rev }; cache.set(state, c); }
  const key = drafts ? "all" : "pub";
  if (!c[key]) c[key] = buildIndex((drafts ? Object.values(state.articles) : published(state)).map((a) => ({ id: a.id, title: a.title, headings: headings(a.body), tags: a.tags, body: plain(a.body) })));
  return c[key];
}
export function find(state, query, limit = 10) { return search(indexOf(state), query, { limit }).map((r) => ({ ...r, article: state.articles[r.id] })); }

// Queries are kept as normalized word lists. Anything that looks like an email address or a long number is dropped before storing.
export function normalizeQuery(q) {
  const s = String(q ?? "").toLowerCase().replace(/\s+/g, " ").trim();
  if (s.length < 2 || s.length > 100 || /@|\d{6,}|https?:/.test(s)) return "";
  return (s.match(/[\p{L}\p{N}]+/gu) || []).join(" ");
}
// `count` is how many results matched every word of the query: a result that matches only some words does not answer the question.
export function logSearch(state, q, count, now) {
  const key = normalizeQuery(q); if (!key) return false;
  const r = state.queries[key] || (state.queries[key] = { q: key, n: 0, zero: 0, clicks: 0, last: 0 });
  r.n++; r.last = now; r.count = count; if (!count) r.zero++;
  const keys = Object.keys(state.queries);
  if (keys.length > 3000) for (const k of keys.sort((a, b) => state.queries[a].last - state.queries[b].last).slice(0, 500)) if (state.queries[k].n < 3) delete state.queries[k];
  return true;
}
export function logClick(state, from) { const r = state.queries[normalizeQuery(from)]; if (r) r.clicks++; }

export function vote(state, id, helpful, comment, now) {
  const a = state.articles[id]; if (!a || a.status !== "published") return false;
  if (helpful) a.yes++; else a.no++;
  const c = oneLine(comment, 500);
  if (!helpful && c) { state.feedback.unshift({ article: id, comment: c, t: now }); state.feedback.length = Math.min(state.feedback.length, 300); }
  return true;
}

// The report this product exists for: what people searched for that the help center could not answer.
export function gaps(state, { minSearches = 1 } = {}) {
  const rows = Object.values(state.queries).filter((r) => r.n >= minSearches).map((r) => ({ ...r, kind: r.count === 0 ? "no results" : r.n >= 3 && r.clicks / r.n < 0.2 ? "results ignored" : "" })).filter((r) => r.kind);
  return rows.sort((a, b) => b.n - a.n || b.last - a.last);
}
export function weakArticles(state, minVotes = 3) {
  return Object.values(state.articles).filter((a) => a.yes + a.no >= minVotes).map((a) => ({ a, share: a.no / (a.yes + a.no) })).filter((x) => x.share >= 0.4).sort((x, y) => y.share - x.share);
}
export function stats(state) {
  const arts = Object.values(state.articles), searches = Object.values(state.queries).reduce((s, r) => s + r.n, 0), zero = Object.values(state.queries).reduce((s, r) => s + r.zero, 0);
  return { articles: arts.length, published: arts.filter((a) => a.status === "published").length, views: arts.reduce((s, a) => s + a.views, 0), searches, zero, helpfulPct: (() => { const y = arts.reduce((s, a) => s + a.yes, 0), n = arts.reduce((s, a) => s + a.no, 0); return y + n ? Math.round((100 * y) / (y + n)) : null; })() };
}

const cell = (v) => { let s = String(v ?? ""); if (/^[=+\-@\t\r]/.test(s)) s = `'${s}`; return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
export function gapsCsv(state) {
  return [["search", "times", "no_result_times", "opened", "kind", "last_seen_utc"], ...gaps(state).map((r) => [r.q, r.n, r.zero, r.clicks, r.kind, new Date(r.last).toISOString()])].map((r) => r.map(cell).join(",")).join("\n") + "\n";
}
export function collections(state) {
  const m = new Map();
  for (const a of published(state)) { const k = a.collection; if (!m.has(k)) m.set(k, { name: k, slug: slugify(k) || "general", articles: [] }); m.get(k).articles.push(a); }
  for (const c of m.values()) c.articles.sort((x, y) => x.title.localeCompare(y.title));
  return [...m.values()].sort((x, y) => x.name.localeCompare(y.name));
}
export { tokens };

markdown.mjs.text:
// A small, safe Markdown renderer for help articles. Browser-safe. Input is escaped first; only the tags built here can appear in output.
// Supported: # headings, paragraphs, - * + and 1. lists, > quotes, ``` code blocks, `code`, **bold**, *italic*, [text](url), ![alt](https://url), ---
export const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

export const slugify = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60);

// Only these link targets survive: http(s), mailto, same-site paths and #anchors. javascript:, data: and the rest become plain text.
export function safeUrl(u, { imageOnly = false } = {}) {
  const s = String(u).trim().replace(/[\u0000-\u001f\u007f\s]+/g, "");
  if (imageOnly) return /^https:\/\/[^\s"'<>]+$/i.test(s) ? s : null;
  if (/^(https?:\/\/|mailto:)[^"'<>]+$/i.test(s)) return s;
  if (/^(\/(?!\/)|#)[^"'<>]*$/.test(s)) return s;
  return null;
}

function inline(raw) {
  const codes = [];
  let s = esc(raw).replace(/`([^`\n]+)`/g, (_, c) => { codes.push(c); return `\u0000${codes.length - 1}\u0000`; });
  s = s.replace(/!\[([^\]]*)\]\(([^)\s]+)\)/g, (m, alt, url) => { const u = safeUrl(url.replace(/&amp;/g, "&"), { imageOnly: true }); return u ? `<img src="${esc(u)}" alt="${alt}" loading="lazy">` : alt; });
  s = s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (m, text, url) => { const u = safeUrl(url.replace(/&amp;/g, "&")); return u ? `<a href="${esc(u)}"${/^https?:/i.test(u) ? ' rel="noopener nofollow"' : ""}>${text}</a>` : text; });
  s = s.replace(/\*\*([^*\n]+)\*\*/g, "<strong>$1</strong>").replace(/(^|[^*\w])\*([^*\n]+)\*(?![*\w])/g, "$1<em>$2</em>");
  return s.replace(/\u0000(\d+)\u0000/g, (_, i) => `<code>${codes[i]}</code>`);
}

export function render(md) {
  const lines = String(md ?? "").replace(/\r\n?/g, "\n").split("\n");
  const out = [], toc = [], used = new Map();
  let i = 0;
  const para = [];
  const flush = () => { if (para.length) { out.push(`<p>${inline(para.join(" "))}</p>`); para.length = 0; } };
  while (i < lines.length) {
    const line = lines[i];
    let m;
    if (/^```/.test(line)) {
      flush(); const code = []; i++;
      while (i < lines.length && !/^```/.test(lines[i])) code.push(lines[i++]);
      i++; out.push(`<pre><code>${esc(code.join("\n"))}</code></pre>`); continue;
    }
    if ((m = /^(#{1,4})\s+(.+?)\s*#*$/.exec(line))) {
      flush(); const level = Math.max(2, m[1].length + 1); // article title is the h1
      let id = slugify(m[2]) || "section"; const n = used.get(id) || 0; used.set(id, n + 1); if (n) id += `-${n + 1}`;
      if (level <= 3) toc.push({ id, text: m[2].replace(/[*`_]/g, ""), level });
      out.push(`<h${level} id="${esc(id)}">${inline(m[2])}</h${level}>`); i++; continue;
    }
    if (/^\s*(-{3,}|\*{3,})\s*$/.test(line)) { flush(); out.push("<hr>"); i++; continue; }
    if (/^>\s?/.test(line)) { flush(); const q = []; while (i < lines.length && /^>\s?/.test(lines[i])) q.push(lines[i++].replace(/^>\s?/, "")); out.push(`<blockquote>${render(q.join("\n")).html}</blockquote>`); continue; }
    if ((m = /^(\s*)([-*+]|\d+[.)])\s+(.*)$/.exec(line))) {
      flush(); const ordered = /\d/.test(m[2]), items = [];
      while (i < lines.length && (m = /^(\s*)([-*+]|\d+[.)])\s+(.*)$/.exec(lines[i]))) {
        let text = m[3]; i++;
        while (i < lines.length && /^\s{2,}\S/.test(lines[i]) && !/^\s*([-*+]|\d+[.)])\s/.test(lines[i])) text += " " + lines[i++].trim();
        items.push(`<li>${inline(text)}</li>`);
      }
      out.push(`<${ordered ? "ol" : "ul"}>${items.join("")}</${ordered ? "ol" : "ul"}>`); continue;
    }
    if (!line.trim()) { flush(); i++; continue; }
    para.push(line.trim()); i++;
  }
  flush();
  return { html: out.join("\n"), toc };
}

// Plain text of the body for search and snippets: no markup characters, link text kept.
export function plain(md) {
  return String(md ?? "").replace(/```[\s\S]*?```/g, (b) => b.replace(/```\w*/g, " ")).replace(/!\[([^\]]*)\]\([^)]*\)/g, "$1").replace(/\[([^\]]+)\]\([^)]*\)/g, "$1").replace(/^#{1,6}\s+/gm, "").replace(/^>\s?/gm, "").replace(/^\s*([-*+]|\d+[.)])\s+/gm, "").replace(/[*_`]/g, "").replace(/\s+/g, " ").trim();
}

export function headings(md) {
  return [...String(md ?? "").replace(/```[\s\S]*?```/g, "").matchAll(/^#{1,6}\s+(.+?)\s*#*$/gm)].map((m) => m[1].replace(/[*_`]/g, ""));
}

render.mjs.text:
// Server-rendered pages. Every dynamic value goes through esc(); article bodies go through markdown.render, which escapes first.
import { esc, render, plain, slugify } from "./markdown.mjs";
import { snippet, related } from "./search.mjs";
import { collections, indexOf, contactHref, gaps, weakArticles, stats, published } from "./kb.mjs";

const css = `:root{font:16px/1.55 system-ui,sans-serif;color:#1c2030;background:#f6f7fb}body{max-width:860px;margin:auto;padding:24px}a{color:#2342b8}h1{line-height:1.15}.card{background:#fff;border:1px solid #dde1ec;border-radius:12px;padding:18px;margin:16px 0}input,select,textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #b5bdd6;border-radius:6px;font:inherit}textarea.code{font:14px/1.4 ui-monospace,monospace;min-height:340px}label{display:block;font-weight:600;margin:10px 0 4px}button{padding:8px 16px;border:0;border-radius:6px;background:#2342b8;color:#fff;font:inherit;cursor:pointer}button.alt{background:#e3e6f1;color:#1c2030}.muted{color:#46506b;font-size:.88rem}table{border-collapse:collapse;width:100%;font-size:.92rem}th,td{text-align:left;padding:6px 8px;border-bottom:1px solid #e3e6f1;vertical-align:top}mark{background:#fff0a8}pre{background:#eef0f8;padding:10px;border-radius:8px;overflow-x:auto}code{background:#eef0f8;padding:1px 4px;border-radius:4px}pre code{padding:0}blockquote{border-left:4px solid #b5bdd6;margin:12px 0;padding:2px 14px;color:#33405e}img{max-width:100%}.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}.pill{display:inline-block;padding:1px 8px;border-radius:99px;font-size:.78rem;background:#e3e6f1}.err{background:#fbd9db;color:#6b0f14;padding:10px 14px;border-radius:8px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px}.grid div{background:#eef0f8;border-radius:8px;padding:10px}.grid b{display:block;font-size:1.4rem}`;

const shell = (cfg, title, body, { desc = "", canonical = "", noindex = false, ld = null, admin = false } = {}) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">${noindex || admin ? '<meta name="robots" content="noindex">' : ""}<title>${esc(title)}</title>${desc ? `<meta name="description" content="${esc(desc)}">` : ""}${canonical ? `<link rel="canonical" href="${esc(canonical)}">` : ""}${ld ? `<script type="application/ld+json">${JSON.stringify(ld).replace(/</g, "\\u003c")}</script>` : ""}<style>${css}</style></head><body><main>
<p class="muted" style="margin:0"><a href="${admin ? "/admin" : "/"}">${esc(admin ? `${cfg.state.settings.name} · admin` : cfg.state.settings.name)}</a></p>${body}
<p class="muted">Answers are provided as-is without warranty and may be out of date.${cfg.sponsor ? ` <a href="https://github.com/sponsors/Duncan-Haywood">Sponsor the author</a>.` : ""}</p></main></body></html>`;

const searchBox = (q = "", s = "") => `<form method="get" action="/search" role="search"><label for="q" class="muted" style="font-weight:400">Search the help center</label><div style="display:flex;gap:8px"><input id="q" name="q" value="${esc(q)}" autocomplete="off" placeholder="${esc(s)}" maxlength="100"><button>Search</button></div></form>`;
const stillStuck = (state) => { const h = contactHref(state.settings.contact); return h ? `<p class="muted">Still stuck? <a href="${esc(h)}">Contact us</a>.</p>` : ""; };
const desc = (a) => plain(a.body).slice(0, 155);

export function homePage(cfg, state) {
  const cols = collections(state), s = state.settings;
  const top = published(state).slice().sort((a, b) => b.views - a.views).filter((a) => a.views > 0).slice(0, 5);
  return shell(cfg, s.name, `<h1>${esc(s.name)}</h1><p>${esc(s.tagline)}</p><div class="card">${searchBox("", "e.g. reset my password")}</div>
${top.length ? `<div class="card"><h2>Popular</h2><ul>${top.map((a) => `<li><a href="/a/${esc(a.slug)}">${esc(a.title)}</a></li>`).join("")}</ul></div>` : ""}
<div class="cols">${cols.map((c) => `<div class="card"><h2><a href="/c/${esc(c.slug)}">${esc(c.name)}</a></h2><ul>${c.articles.slice(0, 6).map((a) => `<li><a href="/a/${esc(a.slug)}">${esc(a.title)}</a></li>`).join("")}</ul>${c.articles.length > 6 ? `<p class="muted"><a href="/c/${esc(c.slug)}">All ${c.articles.length} articles</a></p>` : ""}</div>`).join("") || `<p>No articles yet.</p>`}</div>${stillStuck(state)}`, { desc: s.tagline, canonical: cfg.baseUrl ? `${cfg.baseUrl}/` : "" });
}

export function collectionPage(cfg, state, c) {
  return shell(cfg, `${c.name} · ${state.settings.name}`, `<h1>${esc(c.name)}</h1><div class="card"><ul>${c.articles.map((a) => `<li><a href="/a/${esc(a.slug)}">${esc(a.title)}</a><div class="muted">${esc(plain(a.body).slice(0, 120))}</div></li>`).join("")}</ul></div>${searchBox()}`, { desc: `${c.name} articles`, canonical: cfg.baseUrl ? `${cfg.baseUrl}/c/${c.slug}` : "" });
}

export function searchPage(cfg, state, q, results) {
  const body = results.length ? results.map((r) => `<div class="card"><h2 style="margin:0"><a href="/a/${esc(r.article.slug)}?from=${encodeURIComponent(q.slice(0, 100))}">${esc(r.article.title)}</a></h2><p class="muted" style="margin:4px 0">${esc(r.article.collection)}</p><p>${snippet(plain(r.article.body), q).map((x) => (x.hit ? `<mark>${esc(x.text)}</mark>` : esc(x.text))).join("")}</p></div>`).join("") : `<div class="card"><p>Nothing matched <b>${esc(q)}</b>. Try fewer or different words.</p>${stillStuck(state)}</div>`;
  return shell(cfg, `${q} · Search · ${state.settings.name}`, `<h1>Search</h1><div class="card">${searchBox(q)}</div>${body}`, { noindex: true });
}

export function articlePage(cfg, state, a, { from = "", preview = false, voted = "" } = {}) {
  const r = render(a.body), rel = related(indexOf(state, { drafts: preview }), a.id).map((id) => state.articles[id]).filter((x) => x && (preview || x.status === "published"));
  const url = cfg.baseUrl ? `${cfg.baseUrl}/a/${a.slug}` : "";
  const ld = { "@context": "https://schema.org", "@type": "Article", headline: a.title, dateModified: new Date(a.updated).toISOString(), datePublished: new Date(a.created).toISOString(), articleSection: a.collection, ...(url ? { mainEntityOfPage: url } : {}) };
  return shell(cfg, `${a.title} · ${state.settings.name}`, `${preview ? `<p class="err">Preview${a.status === "draft" ? " — this draft is not public" : ""}.</p>` : ""}<p class="muted"><a href="/c/${esc(encodeCol(a.collection))}">${esc(a.collection)}</a></p><h1>${esc(a.title)}</h1>
${r.toc.length > 2 ? `<nav class="card" aria-label="On this page"><b>On this page</b><ul>${r.toc.map((t) => `<li style="margin-left:${(t.level - 2) * 16}px"><a href="#${esc(t.id)}">${esc(t.text)}</a></li>`).join("")}</ul></nav>` : ""}
<article>${r.html}</article><p class="muted">Updated ${esc(new Date(a.updated).toISOString().slice(0, 10))}</p>
${a.status === "published" && !preview ? (voted ? `<div class="card">Thanks for the feedback.</div>` : `<form method="post" action="/a/${esc(a.slug)}/vote" class="card"><b>Was this helpful?</b> <button name="helpful" value="yes">Yes</button> <button class="alt" name="helpful" value="no">No</button><label for="c" class="muted" style="font-weight:400">If no, what was missing? (optional)</label><input id="c" name="comment" maxlength="500"><input type="hidden" name="from" value="${esc(from)}"></form>`) : ""}
${rel.length ? `<div class="card"><b>Related</b><ul>${rel.map((x) => `<li><a href="/a/${esc(x.slug)}">${esc(x.title)}</a></li>`).join("")}</ul></div>` : ""}${stillStuck(state)}`, { desc: desc(a), canonical: url, noindex: preview || a.status !== "published", ld });
}
const encodeCol = (name) => slugify(name) || "general";

export const notFound = (cfg, state) => shell(cfg, "Not found", `<h1>Not found</h1><p>That page does not exist.</p>${searchBox()}`, { noindex: true });

const dateOf = (t) => new Date(t).toISOString().slice(0, 16).replace("T", " ");

export function adminPage(cfg, state, base, error = "", ok = "") {
  const st = stats(state), arts = Object.values(state.articles).sort((a, b) => b.updated - a.updated);
  const g = gaps(state).length;
  return shell(cfg, "Help center admin", `${error ? `<p class="err" role="alert">${esc(error)}</p>` : ""}${ok ? `<p>${esc(ok)}</p>` : ""}
<div class="card"><div class="grid"><div><b>${st.published}</b>published</div><div><b>${st.views}</b>article views</div><div><b>${st.searches}</b>searches</div><div><b>${st.zero}</b>found nothing</div><div><b>${st.helpfulPct === null ? "—" : `${st.helpfulPct}%`}</b>said helpful</div></div>
<p><a href="/admin/new">New article</a> · <a href="/admin/gaps"><b>Content gaps (${g})</b></a> · <a href="/admin/import">Import</a> · <a href="/admin/export.json">Export JSON</a> · <a href="/" >View site</a></p></div>
